 const stories={call:{name:'The Call',chapter:'CHAPTER 01 · THE CALL',title:'The quiet before the call',text:'Rain threads down the bay doors. The crew has just sat down to breakfast when the tones crackle overhead — a kitchen fire, three blocks east, third floor.',meta:'07:42 AM · ENGINE 17',objective:'Get everyone home',quote:'“The job is never just the fire.”',scenes:[[{t:'Take the direct route',p:'Fastest to the scene, but the flooded underpass is a gamble.',e:'− readiness · + time',m:-2,r:3,n:'The direct route buys you a minute. Water rises around the tires, but Jonah keeps the engine steady.'},{t:'Circle around the underpass',p:'A safer route. You may arrive to a bigger problem.',e:'+ morale · + readiness',m:3,r:1,n:'The longer road is clear. You arrive together, rested and ready.'},{t:'Ask for a second unit',p:'Bring more hands. Trust the extra minute to matter.',e:'+ trust · − time',m:1,r:5,n:'A ladder truck answers. Whatever waits upstairs, no one faces it alone.'}],[{t:'Go in low and fast',p:'Heat is building. The stairwell is still passable.',e:'+ trust · − morale',m:-3,r:5,n:'The hallway is smoke. You find the tenant by following a dog’s frantic scratching.'},{t:'Knock on every door',p:'Turn a rescue into a conversation.',e:'+ trust · + morale',m:4,r:8,n:'Doors open one by one. Neighbors become your extra set of eyes.'},{t:'Vent the roof first',p:'Give the smoke somewhere else to go.',e:'+ readiness · − time',m:1,r:2,n:'The roof hatch gives. Smoke rolls upward, and the stairwell clears.'}],[{t:'Return for the dog',p:'A small bark echoes from the second floor.',e:'+ trust · − morale',m:-2,r:7,n:'You come back with a very relieved terrier. The crowd below cheers.'},{t:'Hand off to the medic',p:'Let the medical team take over.',e:'+ readiness · + morale',m:3,r:3,n:'The medic team moves in. Your crew finally gets a breath.'},{t:'Check the neighbors',p:'Make sure no one is left behind.',e:'+ trust · + morale',m:5,r:6,n:'Everyone is out. A child presses a yellow crayon drawing into Maya’s hand.'}]],end:'The fire is out. The building will need work, but tonight every resident has a key and a place to sleep.'},neighborhood:{name:'Open Doors',chapter:'CHAPTER 02 · OPEN DOORS',title:'The block that forgot to ask',text:'A handwritten note is taped to the station fridge: “Can you teach us what you know?” Across the street, neighbors are gathering in the old laundromat.',meta:'10:16 AM · COMMUNITY ROOM',objective:'Build a safer block',quote:'“Prepared people are powerful people.”',scenes:[[{t:'Open the bay doors',p:'Make the station feel like the neighborhood’s.',e:'+ trust · + morale',m:4,r:7,n:'The bay doors roll up. Kids drift toward the engine, and the adults follow.'},{t:'Bring the training kit',p:'Start with the practical stuff.',e:'+ readiness · + trust',m:2,r:8,n:'You lay out masks and radios. Fear turns into a dozen careful questions.'},{t:'Invite the block inside',p:'Coffee first. Listen before you teach.',e:'+ morale · + trust',m:5,r:6,n:'Stories come out over coffee: loose wires, locked gates, a landlord who never calls back.'}],[{t:'Teach smoke alarms',p:'The small habit that changes everything.',e:'+ trust · + readiness',m:3,r:9,n:'Everyone installs a fresh battery. Mrs. Alvarez writes the test date on her calendar.'},{t:'Map the escape routes',p:'Know two ways out before you need one.',e:'+ trust · + morale',m:4,r:8,n:'The laundromat becomes a map room. Three buildings now have a plan.'},{t:'Run the drill outside',p:'Make practice feel like play.',e:'+ morale · − readiness',m:6,r:5,n:'The kids race the timer. The grownups laugh, then try it again—faster.'}]],end:'When evening arrives, the whole block knows the sound of the alarm—and what to do next. The note on the fridge gets a new line: “Same time next month?”'},rookie:{name:'First Watch',chapter:'CHAPTER 03 · FIRST WATCH',title:'A new pair of boots',text:'Theo has been on the crew for six weeks. On his first overnight watch, an old call comes back through the radio: a warehouse alarm, no visible smoke.',meta:'01:08 AM · NORTH DISTRICT',objective:'Find your rhythm',quote:'“Courage is a team sport.”',scenes:[[{t:'Let Theo lead',p:'Give the new firefighter the first read.',e:'+ morale · + trust',m:5,r:4,n:'Theo studies the quiet warehouse. He spots a glow reflected in a puddle—loading dock, rear side.'},{t:'Take the first look',p:'Demonstrate the scene assessment.',e:'+ readiness · − morale',m:-2,r:7,n:'Maya checks the doors and talks Theo through each choice. He listens closely.'},{t:'Split the team',p:'Cover both sides of the building.',e:'+ trust · − readiness',m:2,r:5,n:'The team moves like a zipper, closing every gap around the warehouse.'}],[{t:'Follow the glow',p:'The reflection is a clue, not a coincidence.',e:'+ trust · + readiness',m:3,r:8,n:'A forklift battery is smoldering behind pallets. Theo finds the shutoff.'},{t:'Call for a thermal camera',p:'Use every tool on the truck.',e:'+ readiness · + trust',m:2,r:9,n:'The camera shows a hot spot behind the paneling—small, but growing.'},{t:'Search for a night watch',p:'Someone may know the building best.',e:'+ morale · + trust',m:4,r:6,n:'A sleepy night guard arrives with a key ring and an important story.'}]],end:'Back at the station, Theo hangs his coat beside the others. The next call comes in—and this time, he is the one who answers.'}};
 let storyKey='call', scene=0, stats={morale:72,trust:38,readiness:91}, completed=new Set();
 const $=id=>document.getElementById(id); const story=()=>stories[storyKey];
 function render(){const s=story();$('chapter').textContent=s.chapter;$('sceneTitle').textContent=scene===s.scenes.length?s.name+' · Complete':(scene?s.title+' · Part '+(scene+1):s.title);$('sceneText').textContent=scene===s.scenes.length?s.end:s.text;$('sceneMeta').textContent=s.meta;$('objective').textContent=scene===s.scenes.length?'Story complete':s.objective;$('quote').innerHTML='“'+s.quote.replace(/[“”]/g,'')+'”<br><span style="font-style:normal;color:#747d82">— Captain Chen</span>';
-const box=$('choices');box.innerHTML=''; if(scene===s.scenes.length){const b=document.createElement('button');b.className='choice';b.innerHTML='<span class="num">OUTCOME <span class="arrow">↗</span></span><h3>Choose another storyline</h3><p>Your choices are written into the station log.</p><span class="effect">Return to the story desk</span>';b.onclick=()=>{$('stories').?.};box.append(b);return} s.scenes[scene].forEach((c,i)=>{const b=document.createElement('button');b.className='choice';b.innerHTML='<span class="num">0'+(i+1)+' <span class="arrow">→</span></span><h3>'+c.t+'</h3><p>'+c.p+'</p><span class="effect">'+c.e+'</span>';b.onclick=()=>choose(c);box.append(b)});updateStats()}
+const box=$('choices');box.innerHTML=''; if(scene===s.scenes.length){const b=document.createElement('button');b.className='choice';b.innerHTML='<span class="num">OUTCOME <span class="arrow">↗</span></span><h3>Choose another storyline</h3><p>Your choices are written into the station log.</p><span class="effect">Return to the story desk</span>';b.onclick=()=>{window.scrollTo({top:0,behavior:'smooth'})};box.append(b);return} s.scenes[scene].forEach((c,i)=>{const b=document.createElement('button');b.className='choice';b.innerHTML='<span class="num">0'+(i+1)+' <span class="arrow">→</span></span><h3>'+c.t+'</h3><p>'+c.p+'</p><span class="effect">'+c.e+'</span>';b.onclick=()=>choose(c);box.append(b)});updateStats()}
 function choose(c){stats.morale=Math.max(0,Math.min(100,stats.morale+c.m));stats.trust=Math.max(0,Math.min(100,stats.trust+c.r));stats.readiness=Math.max(0,Math.min(100,stats.readiness+(c.e.includes('readiness')?2:-1)));log(c.n);scene++;showToast(c.e);render();if(scene===story().scenes.length){completed.add(storyKey);$('completed').textContent=completed.size+' / 3';if(completed.size===3)showToast('All three stories complete — Station 17 stands ready.')}}
 function updateStats(){$('morale').textContent=stats.morale+'%';$('trust').textContent=stats.trust+'%';$('readiness').textContent=stats.readiness+'%';$('moraleBar').style.width=stats.morale+'%';$('trustBar2').style.width=stats.trust+'%';$('readyBar').style.width=stats.readiness+'%';$('trustSmall').textContent=stats.trust+'%';$('trustBar').style.width=stats.trust+'%'}
 function log(text){const item=document.createElement('div');item.className='log-item';item.innerHTML='<b>NOW · FIELD NOTE</b>'+text;$('logList').prepend(item);while($('logList').children.length>3)$('logList').lastChild.remove()}
 function selectStory(key){storyKey=key;scene=0;document.querySelectorAll('.story').forEach(x=>x.classList.toggle('active',x.dataset.story===key));render();showToast(stories[key].name+' storyline selected')}
